CREATE     VIEW [CE].[vwContact]
AS 
SELECT 
	con.[ContactId],
	[rics_countryid],
	[rics_countryidName],
	[CreatedOn],
	[CreatedBy],
	[CreatedByName],
	[ModifiedOn],
	[ModifiedBy],
	[ModifiedByName],
	[TransactionCurrencyId],
	[TransactionCurrencyIdName],
	[MasterId],
	[MasterContactIdName],
	[Rics_FirstQualifiedLocalGroupId],
	[Rics_FirstQualifiedLocalGroupIdName],
	[rics_pathwaytomembershipid],
	[rics_pathwaytomembershipidName],
	[rics_localgroupid],
	[rics_localgroupidName],
	[Address1_City],
	[Address1_Country],
	[address1_Line1],
	[Address1_Line2],
	[Address1_Line3],
	[Address1_PostalCode],
	[Address1_County],
	[Telephone1],
	[OwnerId],
	[OwnerIdName],
	[AccountId],
	[AccountIdName],
	[CustomerSizeCode],
	[CustomerSizeCode_Description],
	[CustomerTypeCode],
	[CustomerTypeCode_Description],
	[LeadSourceCode],
	[LeadSourceCode_Description],
	[OriginatingLeadId],
	[OriginatingLeadIdName],
	[Salutation],
	[JobTitle],
	[FirstName],
	[MiddleName],
	[LastName],
	[FullName],
	[BirthDate],
	[GenderCode],
	[GenderCode_Description],
	[TerritoryCode],
	[TerritoryCode_Description],
	[IsPrivate],
	[CreditOnHold],
	[CreditLimit],
	[Aging30],
	[StateCode],
	[StateCode_Description],
	[StatusCode],
	[StatusCode_Description],
	[Aging60],
	[Aging90],
	[ParentCustomerId],
	[ParentCustomerIdName],
	[ParentCustomerIdType],
	[Merged],
	[Rics_Renewals],
	[Rics_ElectionDate],
	[Rics_Honours],
	[Rics_contactno],
	COALESCE([Rics_MemberGrade], -1) AS Rics_MemberGrade,
	[MemberGrade_Description],
	[apuk_regionid],
	[Rics_Region],
	[Rics_LapsedDate],
	[Rics_LapsedCode],
	[Rics_LapsedCode_Description],
	[Rics_PaymentMethod],
	[Rics_PaymentMethod_Description],
	[Rics_ConcessionCode],
	[Rics_ConcessionCode_Descritpion],
	[Rics_Donotchase],
	[Rics_Donotchase_Description],
	[MobilePhone],
	[Rics_MailName],
	[EMailAddress1],
	[Rics_corespadd_country],
	[Rics_PaymentCycle],
	[Rics_PaymentCycle_Description],
	[Rics_PreventLapse],
	[Rics_PreventLapse_Description],
	[Rics_PendingRemoval],
	[Rics_PendingRemovalDate],
	[Rics_HardcopySubs],
	[Rics_Disability],
	[Rics_Ethnicity],
	[Rics_Ethnicity_Description],
	[rics_primaryprofessionalgroupid],
	[rics_primaryprofessionalgroupidName],
	apuk_professionalgroupid,
	[Rics_DualMembership],
	[Rics_DualMembership_Description],
	[Rics_ContactType],
	[Rics_ContactType_Description],
	[ricsv1_Counsellor],
	[rics_receiveenewsletter],
	[rics_corespadd_city],
	[EmailAddress2],
	[EmailAddress3],
	[Telephone3],
	[Rics_AssessorAuditor],
	[Rics_AssessorChairman],
	[Rics_EmailPreference],
	[Rics_EmailPreference_Description],
	[Rics_AddressPreference],
	[Rics_AddressPreference_Description],
	[Rics_PhonePreference],
	[Rics_PhonePreference_Description],
	[apuk_disabilitiesdetails],
	[apuk_eminentmember],
	[apuk_ricsrecordid],
	[apuk_applicanttype],
	[apuk_applicanttype_description],
	[apuk_designation],
	[apuk_designation_description],
	[apuk_giftaid],
	[apuk_declinelionheart],
	DATEDIFF(YY,[BirthDate], GETDATE()) [CurrentAge],
	CASE 
		WHEN CAST(ISNULL([BirthDate],'1900-01-01') AS DATE) = '1900-01-01' OR DATEDIFF(YY,[BirthDate], GETDATE()) < 16 OR [BirthDate] >= GETDATE() THEN NULL 
		ELSE DATEDIFF(YY,[BirthDate], GETDATE())
	END [AdjustedAge],
	[address2_line1],
	[address2_postalcode],
	[address2_country],
	[apuk_personaladdresscountryid],
	[apuk_personaladdresscountryidName],
	[apuk_sexualorientation], 
	[apuk_genderidentity], 
	[apuk_religionorbelief], 
	[apuk_ethnicityother], 
	[apuk_disabilities],
	[address1_longitude],
	[address1_latitude],
	[apuk_hasdisability2],
	[apuk_hasdisability2_description],
	[apuk_drsdisputeresolver],
	[apuk_drspanelenddate],
	[apuk_drspanelmemberonhold],
	[address2_line2],
	[address2_line3],
	[address2_city],
	[address2_county]


FROM [synapse_ce].[tblContact_BI] CON
	--LEFT JOIN Static.tblTestContacts TST ON TST.apuk_contactnumber = CON.Rics_contactno
	LEFT JOIN CE.tblContact_Test_Records TST ON TST.apuk_contactnumber = CON.Rics_contactno

WHERE Rics_contactno IS NOT NULL
	AND con.ContactId <> '00000000-0000-0000-0000-000000000000' --Duplicate member not active
	AND TST.apuk_contactnumber IS NULL
--WHERE [StateCode] = 0
